CREATE OR ALTER PROCEDURE DBO.SPK_GEN_TRAMAS_DOMI_PERU 
@ENVIO VARCHAR(6),
@TRAMARES043 BIT = 0
WITH ENCRYPTION
AS  
DECLARE @EXISTE INT
DECLARE @IDSSEGU VARCHAR(20)
DECLARE @NITIPS  VARCHAR(20)
   DECLARE 
    @VLR_HONOR_SIN_IGV      DECIMAL(14,2)
   ,@VLR_ODONTO_SIN_IGV     DECIMAL(14,2)
   ,@VLR_HSCT_SIN_IGV       DECIMAL(14,2)
   ,@VLR_LAB_SIN_IGV        DECIMAL(14,2)
   ,@VLR_RX_SIN_IGV         DECIMAL(14,2)
   ,@VLR_INV_SIN_IGV        DECIMAL(14,2)
   ,@VLR_PROTESIS_SIN_IGV   DECIMAL(14,2)
   ,@VLR_OTROS_SIN_IGV      DECIMAL(14,2)
   ,@VLR_MED_EXONE          DECIMAL(14,2)
   ,@BASEIMP                DECIMAL(14,2)
   ,@IDSER                  VARCHAR(20)
   ,@DIF                    DECIMAL(14,2)
   ,@SUMADETALLE            DECIMAL(14,2)
   ,@ITEM                   INT
   ,@N_FACTURA              VARCHAR(20)
BEGIN
	
	PRINT 'INGRESO A SPK_GEN_TRAMAS_DOMI_PERU'

   DELETE TRAMA_DATE WHERE IDTRAMA=@ENVIO
   DELETE TRAMA_DSER WHERE IDTRAMA=@ENVIO
   DELETE TRAMA_DFAC WHERE IDTRAMA=@ENVIO
   DELETE TRAMA_DFAR WHERE IDTRAMA=@ENVIO

   SELECT @IDSSEGU=COALESCE(IDALTERNA2,NIT),@NITIPS=NIT FROM TER WHERE IDTERCERO=DBO.FNK_VALORVARIABLE('IDTERCEROINSTALADO')


  INSERT INTO TRAMA_DFAC(IDTRAMA, F_ENVIO, NUM_LOTE, COD_IAFAS, IDRUC, COD_IPRESS, TDOC_PAGO, NUMDOC_PAGO, F_EMISION, PRODUCTO, 
                            N_PRESTACIONES, MPAGO, SUB_MPAGO, VLR_PREPACTADO, F_INICIO_PER, TMONEDA, VLR_EXONERADO,  VLR_COPAGO_FIJO, 
                            VLR_COPAGO_FIJO_EX, VLR_COPAGO_VAR, VLR_COPAGO_VAR_EX, VLR_BASEIMP, VLR_IGV, VLR_TOTAL, CLASE, CNSFNOT, 
                            VLR_TOTAL_NOTA, F_NOTA, M_NOTA, F_PENVIO_FTR, IND_FTR )
   SELECT @ENVIO,RIPS.FECHAENVIO,REPLACE(SPACE(7-LEN(RIPS.ENVIO)),SPACE(1),0)+RIPS.ENVIO,LEFT(COALESCE(TER.IDALTERNA2,NIT),5),LEFT(@NITIPS,11),COALESCE(DBO.FNK_BUSCA_RENIPRESS(FTR.N_FACTURA),LEFT(@IDSSEGU,8)),'01',
   DBO.FNK_TRANSFORMA_NFACTURA(FTR.N_FACT_EXTERNO),
   FTR.F_FACTURA,S.codiProducto,
   CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(5-LEN('1')),SPACE(1),0)+LTRIM(RTRIM(STR(1))) ELSE LTRIM(RTRIM(STR(1))) END,
   CASE WHEN RIPSD.MEC_FACT = 'CPM' THEN '02'ELSE '01' END,
   --CASE WHEN RIPSD.MEC_FACT = 'CPM' THEN '011' ELSE '999' END,
   CASE WHEN RIPSD.MEC_FACT = 'CPM' 
		THEN CASE WHEN '28' = (SELECT IDEMEDICA FROM MED WHERE IDMEDICO = (SELECT DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'IDMEDICO'))) THEN '025' ELSE '024' END -- 024 MAD GENERAL, 025 MAD PEDIATRICO.
		ELSE '999' 
	END,
   CASE WHEN FTR.MEC_FACT IN ('PPS','MER') THEN 0.00 ELSE FTRD.VALOR_UNITARIO_SIN_IGV END,
   CASE WHEN FTR.MEC_FACT = 'CPM' THEN COALESCE(S.FECHA_AUTORIZA,(SELECT MIN(FTRD.FECHAPREST)FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA)) ELSE NULL END
   ,1,
   CASE WHEN COALESCE(FTR.VIVA,0)<=0 THEN FTR.VALORSERVICIOS ELSE 0.00 END
   ,COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA = 'CI' AND PAQUETE = 1),0.00),0.00,
   COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA <> 'CI' AND PAQUETE = 1),0.00),0.00,
   CASE WHEN COALESCE(FTR.VIVA,0)>0 THEN FTR.VR_TOTAL-(COALESCE(FTR.VIVA,0)) ELSE 0.00 END,
   COALESCE(FTR.VIVA,0),FTR.VR_TOTAL ,'N',NULL,NULL,NULL,NULL,NULL,'N'
   FROM RIPSD INNER JOIN RIPS ON RIPSD.ENVIO=RIPS.ENVIO
              INNER JOIN FTR ON RIPSD.N_FACTURA=FTR.N_FACTURA
			  INNER JOIN FTRD ON FTR.N_FACTURA=FTRD.N_FACTURA
			  INNER JOIN MAD ON MAD.ID=FTRD.NOADMISION AND FTRD.PAQUETE = 0
              INNER JOIN TER ON FTR.IDTERCERO=TER.IDTERCERO
              LEFT JOIN FDIAN ON FTR.CNSRESOL=FDIAN.CNSRESOL
              LEFT JOIN AFI  ON FTR.IDAFILIADO=AFI.IDAFILIADO
			  --LEFT JOIN TRAMA_SITEDS S ON FTR.VENDEDOR=S.NAUTORIZACION
			  LEFT JOIN CONSSITEDS S ON S.CONSECUTIVO=MAD.ID AND S.PROCEDENCIA = 'MAD'
			  LEFT JOIN CITSITEDS CS ON MAD.ID = CS.CONSECUTIVO AND CS.PROCEDENCIA = 'MAD'
   WHERE RIPSD.ENVIO=@ENVIO
   ORDER BY FTR.N_FACT_EXTERNO

   --------------------------------------------------------------------------------------------

   ;WITH Totales AS (
    SELECT 
        FTR.N_FACTURA,
        MIN(FTRD.FECHAPREST) AS MinFechaPrest,
		CASE WHEN FTR.MEC_FACT = 'CPM' THEN 
			SUM(CASE WHEN FTRD.PROCEDENCIA = 'CI'
					 THEN FTRD.CANTIDAD * F.VALOR_UNITARIO_SIN_IGV 
					 ELSE 0 END)
		ELSE
			SUM(CASE WHEN FTRD.PROCEDENCIA <> 'CE'
					 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV
					 ELSE 0 END)
		END	AS TotalHonor,
        SUM(CASE WHEN PRE.CODRUBRO='03' 
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END) AS TotalHSCT,
        SUM(CASE WHEN PRE.CODRUBRO='06' 
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END) AS TotalRX,
        SUM(CASE WHEN PRE.CODRUBRO='15' 
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END) AS TotalOtros,
        SUM(CASE WHEN PRE.CODRUBRO='05' AND COALESCE(FTRD.VALOR_IGV_UNITARIO,0)<=0 
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END) AS TotalMedExone,
				 
		CASE WHEN FTR.MEC_FACT = 'CPM' THEN 
			SUM(CASE WHEN FTRD.PREFIJO = DBO.FNK_VALORVARIABLE('PREFIJOLABORATORIO') 
                  AND FTRD.PAQUETE = 1 
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END)
		ELSE
			SUM(CASE WHEN FTRD.PROCEDENCIA = 'CE'
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END)
		END AS TotalLab,
        SUM(CASE WHEN FTRD.PREFIJO IN (DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS'),
                                       DBO.FNK_VALORVARIABLE('PREFIJOMATERIALES'))
                  AND FTRD.PAQUETE = 1
                 THEN FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV ELSE 0 END) AS TotalMedsMat,
        CASE WHEN FTR.MEC_FACT = 'CPM' THEN 
			SUM(CASE WHEN FTRD.PROCEDENCIA = 'CI'
					 THEN FTRD.CANTIDAD * F.VALOR_UNITARIO_SIN_IGV 
					 ELSE FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV END)
		ELSE
			SUM(FTRD.CANTIDAD * FTRD.VALOR_UNITARIO_SIN_IGV)
		END AS TotalValor
    FROM RIPSD
	INNER JOIN RIPS ON RIPSD.ENVIO=RIPS.ENVIO
	INNER JOIN FTR ON RIPSD.N_FACTURA=FTR.N_FACTURA
	INNER JOIN FTRD ON FTR.N_FACTURA=FTRD.N_FACTURA
    INNER JOIN PRE ON FTRD.PREFIJO = PRE.PREFIJO
    CROSS APPLY DBO.FNQ_VAL_SERTOT_PERU(FTRD.FECHA,FTR.IDTERCERO,FTR.IDPLAN,DBO.FNK_VALORVARIABLE('MAD_SER_HOMCPM')) F
    WHERE RIPSD.ENVIO=@ENVIO AND FTRD.PAQUETE = IIF(FTR.MEC_FACT IN ('PPS','MER'),0, 1)
    GROUP BY FTR.N_FACTURA,FTR.MEC_FACT
)
	--SELECT * FROM Totales
	--RETURN
    INSERT INTO TRAMA_DATE (IDTRAMA, IDRUC, COD_IPRESS, TDOC_PAGO, NUMDOC_PAGO, CORRELATIVO, CODINTERNO, TIPO_AFILIADO, COD_ASE_PACIENTE, 
               TIPO_DOC_AFI, DOC_AFILIADO, NUM_HCA, DOC_AUT, NUM_AUT, DOC_AUT2, NUM_AUT2,  TCOBERTURA, SUB_COBERTURA, IDDX, IDDX2, IDDX3, F_PRESTACION, 
               TIPO_PROF_RESPONSABLE, NUM_CPRP, TIPO_DOC, NUM_DOC, IDRUC_REF, F_TRANSFERENCIA, TIPO_HOSP, F_INGRESO, F_EGRESO, TIPO_EGRESO,  
               DIAS_ESTANCIA, VLR_HONOR_SIN_IGV , VLR_ODONTO_SIN_IGV, VLR_HSCT_SIN_IGV, VLR_LAB_SIN_IGV, VLR_RX_SIN_IGV, VLR_INV_SIN_IGV, 
               VLR_PROTESIS_SIN_IGV, VLR_OTROS_SIN_IGV, COPAGO_FIJO,  COPAGO_FIJO_EXO, COPAGO_VAR, COPAGO_VAR_EXO, TOTAL_GASTOS,VLR_MED_EXONE
               )

   SELECT  @ENVIO,LEFT(@NITIPS,11),COALESCE(DBO.FNK_BUSCA_RENIPRESS(FTR.N_FACTURA),LEFT(@IDSSEGU,8)),'01',DBO.FNK_TRANSFORMA_NFACTURA(FTR.N_FACT_EXTERNO),
   CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(5-LEN('1')),SPACE(1),0)+LTRIM(RTRIM(STR(1))) ELSE LTRIM(RTRIM(STR(1))) END,CASE WHEN FTR.MEC_FACT IN ('CPM','MER') THEN (SELECT MIN(FTRD.NOADMISION) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PAQUETE = 0) ELSE RIGHT(FTR.NOREFERENCIA,8) END,COALESCE(AFI.SISBENNIVEL,1),COALESCE(S.AFIcodiAse,AFI.IDALTERNA,AFI.DOCIDAFILIADO),TGEN.DATO5,
   AFI.DOCIDAFILIADO, RIGHT((SELECT MIN(MAD.IDAFILIADO) FROM MAD WHERE FTR.N_FACTURA=IIF(FTR.MEC_FACT IN ('CPM','MER'),MAD.N_FACTURA,MAD.N_FACTURA_PPS)),8),'01',COALESCE(MAD.NOAUTORIZACION,''),'99','',COALESCE(CS.ID_TIPO_COBERTURA,'1'),COALESCE(CS.ID_COPAGOCONSULTA_DESC,'289'),--COALESCE(HADMAUT.TIPOCOBER,'1'),COALESCE(HADMAUT.SUBTIPOCOBER,'289'),--tipocites
   DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC1'),NULL,--DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC2'),
   NULL,-- DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC3'),
   MIN(FTRD.FECHAPREST),COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_RES'),'00'),LEFT(COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'N_REG'),''),6),
   COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_DOC'),''),COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'IDMEDICO'),''),--fechaatencion
   LEFT(@NITIPS,11),NULL,'',NULL,NULL,'','',
   --SUM(CASE WHEN PRE.CODRUBRO='02' THEN IIF(FTR.MEC_FACT = 'CPM',F.VALOR_UNITARIO_SIN_IGV,FTRD.VALOR_UNITARIO_SIN_IGV) ELSE 0.00 END),
   COALESCE(T.TotalHonor,0.00),0.00,COALESCE(T.TotalHSCT,0.00),COALESCE(T.TotalLab,0.00),COALESCE(T.TotalRX,0.00),COALESCE(T.TotalMedsMat,0.00),0.00,COALESCE(T.TotalOtros,0.00),
   COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA = 'CI' AND PAQUETE = 1),0.00),0.00,
   COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA <> 'CI' AND PAQUETE = 1),0.00),0.00,
   T.TotalValor,COALESCE(T.TotalMedExone,0.00)
   FROM RIPSD INNER JOIN RIPS ON RIPSD.ENVIO=RIPS.ENVIO
              INNER JOIN FTR ON RIPSD.N_FACTURA=FTR.N_FACTURA
              INNER JOIN FTRD ON FTR.N_FACTURA=FTRD.N_FACTURA AND FTRD.PAQUETE = 0
			  INNER JOIN Totales T ON T.N_FACTURA = FTR.N_FACTURA
              INNER JOIN PRE ON FTRD.PREFIJO=PRE.PREFIJO
              INNER JOIN AFI ON FTR.IDAFILIADO=AFI.IDAFILIADO
              INNER JOIN TER ON FTR.IDTERCERO=TER.IDTERCERO
			  INNER JOIN MAD ON FTRD.NOADMISION = MAD.ID AND FTRD.PAQUETE = 0
              LEFT JOIN FDIAN ON FTR.CNSRESOL=FDIAN.CNSRESOL
              LEFT JOIN TGEN ON AFI.TIPO_DOC=TGEN.CODIGO AND TGEN.TABLA='General' AND TGEN.CAMPO='TIPOIDENT'
              LEFT JOIN PPT ON FTR.IDTERCERO=PPT.IDTERCERO AND FTR.IDPLAN=PPT.IDPLAN
			  LEFT JOIN CONSSITEDS S ON S.CONSECUTIVO=MAD.ID AND S.PROCEDENCIA = 'MAD'
			  LEFT JOIN CITSITEDS CS ON MAD.ID = CS.CONSECUTIVO AND CS.PROCEDENCIA = 'MAD'
			  CROSS APPLY DBO.FNQ_VAL_SERTOT_PERU(FTRD.FECHA,FTR.IDTERCERO,FTR.IDPLAN,DBO.FNK_VALORVARIABLE('MAD_SER_HOMCPM')) F
   WHERE RIPSD.ENVIO=@ENVIO
	AND NOT EXISTS(SELECT * FROM ESP WHERE ESP.IDPROVEEDOR=FTR.IDTERCERO AND FTR.IDPLAN=ESP.IDPLAN AND FTRD.REFERENCIA=ESP.IDSERVICIO AND COALESCE(ESP.PAQUETE,0)=1)
   GROUP BY FTR.N_FACTURA,RIGHT(FTRD.NOPRESTACION,9),COALESCE(AFI.SISBENNIVEL,1),AFI.IDALTERNA,TGEN.DATO5,COALESCE(CS.ID_TIPO_COBERTURA,'1'),COALESCE(CS.ID_COPAGOCONSULTA_DESC,'289'),
   AFI.DOCIDAFILIADO, RIGHT(FTR.NOREFERENCIA,8),FTR.VENDEDOR,DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC1'),
   FTR.F_FACTURA,COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_RES'),'00'),LEFT(COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'N_REG'),''),6),
   COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_DOC'),''),COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'IDMEDICO'),''),FTR.MEC_FACT,MAD.NOAUTORIZACION,S.AFIcodiAse,FTR.N_FACT_EXTERNO,
   T.TotalHonor,T.TotalHSCT,T.TotalLab,T.TotalRX,T.TotalMedsMat,T.TotalOtros,T.TotalValor,T.TotalMedExone
   ORDER BY FTR.N_FACT_EXTERNO

   --------------------------------------------------------------------------------------------


   INSERT INTO TRAMA_DSER(IDTRAMA, IDRUC, COD_IPRESS, TDOC_PAGO, NUMDOC_PAGO,CORRELATIVO,CORRE_PRESTA, TIPO_CLASIFICACION, IDSERVICIO, DESCSERVICIO, 
               FECHA_PROC, IDEMEDICA, NUM_CPR, TIPO_DOC_PRO, IDMEDICO, CANTIDAD, VLR_UNITARIO,  VLRCOPAGO_VARIABLE, VLRCOPAGO_FIJO, VLR_TOTAL, 
               VLR_NOCUBIERTO, IDDX, SER_EXENTO, COD_RUBRO,CANT_PRESCRITA,RESULTADO )

   SELECT @ENVIO,LEFT(@NITIPS,11),COALESCE(DBO.FNK_BUSCA_RENIPRESS(FTR.N_FACTURA),LEFT(@IDSSEGU,8)),'01',
   DBO.FNK_TRANSFORMA_NFACTURA(FTR.N_FACT_EXTERNO),
   CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(5-LEN('1')),SPACE(1),0)+LTRIM(RTRIM(STR(1))) ELSE LTRIM(RTRIM(STR(1))) END,
   --CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(4-LEN(FTRD.N_CUOTA)),SPACE(1),0)+LTRIM(RTRIM(STR(FTRD.N_CUOTA))) ELSE LTRIM(RTRIM(STR(FTRD.N_CUOTA))) END,
   CASE 
		WHEN @TRAMARES043 = 0 
			THEN REPLACE(
					 SPACE(4 - LEN(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))),
					 SPACE(1),
					 '0'
				 ) + LTRIM(RTRIM(STR(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))))
		ELSE 
			LTRIM(RTRIM(STR(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))))
	END,
   IIF(@TRAMARES043=1,COALESCE(PRE.TIPOTRMA,'03'),COALESCE(PRE.TIPOTRMA,'03')),IIF(@TRAMARES043=1,LEFT(SER.CODTRAMA,10),LEFT(SER.IDALTERNA,10))
   ,IIF(@TRAMARES043=1,LEFT(SER.DESC_TRAMA,70),LEFT(SER.DESCRIPCION_CUPS,70))DESCSERVICIO,CASE WHEN COALESCE(S.NAUTORIZACION,'')<>'' THEN S.FAUTORIZA ELSE  FTRD.FECHA END,
   COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_RES'),'00'),
   COALESCE(LEFT(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'N_REG'),6),''),
   DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'TIPO_DOC'),
   COALESCE(DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'IDMEDICO'),''),
   CONVERT(INT,FTRD.CANTIDAD),--REPLACE(SPACE(5-LEN(CONVERT(INT,FTRD.CANTIDAD))),SPACE(1),0)+LTRIM(RTRIM(STR(FTRD.CANTIDAD))),
   IIF(FTR.MEC_FACT = 'CPM' AND FTRD.PROCEDENCIA = 'CI',F.VALOR_UNITARIO_SIN_IGV,FTRD.VALOR_UNITARIO_SIN_IGV)
   --,COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA <> 'CI' AND PAQUETE = 1),0.00)
   ,CASE WHEN FTRD.PROCEDENCIA <> 'CI' THEN COALESCE(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV,0.00) ELSE  0.00 END
   --,COALESCE((SELECT SUM(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV) FROM FTRD WHERE FTRD.N_FACTURA=FTR.N_FACTURA AND FTRD.PROCEDENCIA = 'CI' AND PAQUETE = 1),0.00)
   ,CASE WHEN FTRD.PROCEDENCIA = 'CI' THEN COALESCE(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV,0.00) ELSE  0.00 END 
   ,CONVERT(DECIMAL(14,2),FTRD.CANTIDAD*IIF(FTR.MEC_FACT = 'CPM' AND FTRD.PROCEDENCIA = 'CI',F.VALOR_UNITARIO_SIN_IGV,FTRD.VALOR_UNITARIO_SIN_IGV)),0.00,DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC1'),
   'A',CASE WHEN FTR.MEC_FACT IN ('PPS','MER') AND FTRD.PROCEDENCIA = 'CE' THEN '03' ELSE COALESCE(PRE.CODRUBRO,'02') END
   ,0.00,NULL
   FROM RIPSD INNER JOIN RIPS ON RIPSD.ENVIO=RIPS.ENVIO
              INNER JOIN FTR ON RIPSD.N_FACTURA=FTR.N_FACTURA
              INNER JOIN AFI ON FTR.IDAFILIADO=AFI.IDAFILIADO
              INNER JOIN FTRD ON FTR.N_FACTURA=FTRD.N_FACTURA AND RIPSD.N_FACTURA=FTRD.N_FACTURA AND FTRD.PAQUETE = IIF(FTR.MEC_FACT IN ('PPS','MER'),0, 1)
              INNER JOIN TER ON FTR.IDTERCERO=TER.IDTERCERO
              INNER JOIN SER ON CASE WHEN FTRD.PROCEDENCIA='CI' AND FTR.MEC_FACT = 'CPM' AND FTRD.PAQUETE = 1 THEN DBO.FNK_VALORVARIABLE('MAD_SER_HOMCPM') ELSE FTRD.REFERENCIA END=SER.IDSERVICIO
              INNER JOIN PRE ON SER.PREFIJO=PRE.PREFIJO
              LEFT JOIN FDIAN ON FTR.CNSRESOL=FDIAN.CNSRESOL
              LEFT JOIN TGEN ON AFI.TIPO_DOC=TGEN.CODIGO AND TGEN.TABLA='General' AND TGEN.CAMPO='TIPOIDENT'
              LEFT JOIN TRAMA_SITEDS S ON FTR.VENDEDOR=S.NAUTORIZACION
			  CROSS APPLY DBO.FNQ_VAL_SERTOT_PERU(FTRD.FECHA,FTR.IDTERCERO,FTR.IDPLAN,DBO.FNK_VALORVARIABLE('MAD_SER_HOMCPM')) F
   WHERE RIPSD.ENVIO=@ENVIO
   AND PRE.PREFIJO NOT IN (DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS'), DBO.FNK_VALORVARIABLE('PREFIJOMATERIALES'))
   AND NOT EXISTS(SELECT * FROM ESP WHERE ESP.IDPROVEEDOR=FTR.IDTERCERO AND FTR.IDPLAN=ESP.IDPLAN AND FTRD.REFERENCIA=ESP.IDSERVICIO AND COALESCE(ESP.PAQUETE,0)=1)
   ORDER BY FTR.N_FACT_EXTERNO, FTRD.N_CUOTA


   --------------------------------------------------------------------------------------------


   INSERT INTO TRAMA_DFAR (IDTRAMA, IDRUC, COD_IPRESS, TDOC_PAGO, NUMDOC_PAGO, CORRELATIVO, CORRE_PRESTA, TPRODUC, 
   TCATALOGO, IDSERVICIO, FDISPENSA, CANTIDAD, TDISPENSA, VLRUNITA, VLCOPAGO, VLTOTAL, VLNOCUBIERTO,  IDDX, EXENTO, 
   GUIAENTREGA,CANT_PRESCRITA)
   SELECT @ENVIO,LEFT(@NITIPS,11),COALESCE(DBO.FNK_BUSCA_RENIPRESS(FTR.N_FACTURA),LEFT(@IDSSEGU,8)),'01',
   DBO.FNK_TRANSFORMA_NFACTURA(FTR.N_FACT_EXTERNO),
   CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(5-LEN('1')),SPACE(1),0)+LTRIM(RTRIM(STR(1))) ELSE LTRIM(RTRIM(STR(1))) END,
   --CASE WHEN @TRAMARES043 = 0 THEN REPLACE(SPACE(4-LEN(FTRD.N_CUOTA-1)),SPACE(1),0)+LTRIM(RTRIM(STR(FTRD.N_CUOTA-1))) ELSE LTRIM(RTRIM(STR(FTRD.N_CUOTA-1))) END,
   CASE 
		WHEN @TRAMARES043 = 0 
			THEN REPLACE(
					 SPACE(4 - LEN(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))),
					 SPACE(1),
					 '0'
				 ) + LTRIM(RTRIM(STR(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))))
		ELSE 
			LTRIM(RTRIM(STR(ROW_NUMBER() OVER (PARTITION BY FTR.N_FACTURA ORDER BY FTRD.N_CUOTA))))
	END,
   CASE WHEN FTRD.PREFIJO=DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS') and ANEXO NOT LIKE '%AGUJA%' THEN  'M' ELSE 'I' END,
   CASE WHEN FTRD.PREFIJO=DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS') and ANEXO NOT LIKE '%AGUJA%' THEN  1 ELSE 2 END,LEFT(SER.CODCUPS,13),CASE WHEN COALESCE(S.NAUTORIZACION,'')<>'' THEN S.FAUTORIZA ELSE  FTRD.FECHA END,
   CONVERT(INT,FTRD.CANTIDAD),1,COALESCE(FTRD.VALOR_UNITARIO_SIN_IGV,0),CONVERT(DECIMAL(14,2),COALESCE(FTRD.VALOR_COPAGO_TOTAL_SIN_IGV,0)),CONVERT(DECIMAL(14,2),FTRD.CANTIDAD*FTRD.VALOR_UNITARIO_SIN_IGV),
   0, DBO.FNK_BUSCADATOSTRAMAS(RIPSD.N_FACTURA,'DXHC1'),
   CASE WHEN COALESCE(FTRD.VALOR_IGV_UNITARIO,0)>0 THEN 'A' ELSE 'D' END,
   RIGHT(REPLICATE('0', 12) + COALESCE(AUT.CNSMOV, FTRD.NOPRESTACION), 12)
   ,0.00
   FROM RIPSD INNER JOIN RIPS ON RIPSD.ENVIO=RIPS.ENVIO
              INNER JOIN FTR ON RIPSD.N_FACTURA=FTR.N_FACTURA
              INNER JOIN AFI ON FTR.IDAFILIADO=AFI.IDAFILIADO
              INNER JOIN FTRD ON FTR.N_FACTURA=FTRD.N_FACTURA AND RIPSD.N_FACTURA=FTRD.N_FACTURA-- AND FTRD.PAQUETE = 1
			  LEFT JOIN AUT ON AUT.IDAUT=FTRD.NOPRESTACION
			   LEFT JOIN (
					SELECT IDAUT, IDSERVICIO_AUTD, MIN(IDSERVICIO) IDSERVICIO, MIN(ID) AS ID -- elijo un registro único
					FROM AUTDF
					GROUP BY IDAUT, IDSERVICIO_AUTD
				) AUTDF ON AUTDF.IDSERVICIO_AUTD = FTRD.REFERENCIA 
					   AND AUTDF.IDAUT = FTRD.NOPRESTACION
			INNER JOIN SER ON SER.IDSERVICIO=AUTDF.IDSERVICIO 
			INNER JOIN TER ON FTR.IDTERCERO=TER.IDTERCERO
			--INNER JOIN SER ON FTRD.REFERENCIA=SER.IDSERVICIO
			INNER JOIN PRE ON SER.PREFIJO=PRE.PREFIJO
            LEFT JOIN TRAMA_SITEDS S ON FTR.VENDEDOR=S.NAUTORIZACION
   WHERE RIPSD.ENVIO=@ENVIO
   AND PRE.PREFIJO IN (DBO.FNK_VALORVARIABLE('PREFIJOMEDICAMENTOS'), DBO.FNK_VALORVARIABLE('PREFIJOMATERIALES'))
    --AND (COALESCE(SER.MEDICAMENTOS,0)=1 OR ISNULL(PRE.MINVENTARIOS,0)=1)
   ORDER BY FTR.N_FACT_EXTERNO, FTRD.N_CUOTA

   
   PRINT 'TERMINO INSERT DE TRAMA_DFAR '

   UPDATE TRAMA_DATE SET TRAMATEX=CAST(CASE WHEN LEN(COALESCE(IDRUC,''))<11 THEN REPLACE(SPACE(11-LEN(COALESCE(IDRUC,''))),SPACE(1),CHAR(10))+COALESCE(IDRUC,'') ELSE LEFT(COALESCE(IDRUC,''),11) END AS VARCHAR(11))+
   CAST(CASE WHEN LEN(COALESCE(COD_IPRESS,''))<8 THEN REPLACE(SPACE(8-LEN(COALESCE(COD_IPRESS,''))),SPACE(1),'0')+COALESCE(COD_IPRESS,'') ELSE LEFT(COALESCE(COD_IPRESS,''),8) END AS VARCHAR(8))+
