   CAST(CASE WHEN LEN(COALESCE(COD_ASE_PACIENTE,''))<20 THEN REPLACE(SPACE(20-LEN(COALESCE(COD_ASE_PACIENTE,''))),SPACE(1),CHAR(10))+COALESCE(COD_ASE_PACIENTE,'') ELSE LEFT(COALESCE(COD_ASE_PACIENTE,''),20) END AS VARCHAR(20))+
